class RestoringWalletCard extends ConsumerStatefulWidget {
  const RestoringWalletCard({super.key, required this.provider});

  final ChangeNotifierProvider<WalletRestoreState> provider;

  @override
  ConsumerState<RestoringWalletCard> createState() =>
      _RestoringWalletCardState();
}

class _RestoringWalletCardState extends ConsumerState<RestoringWalletCard> {
  late final ChangeNotifierProvider<WalletRestoreState> provider;

  Future<void> _retry() async {
    final wallet = ref.read(provider).wallet!;
    final uiState = ref.read(stackRestoringUIStateProvider);
    var didExit = false;
    try {
      uiState.update(
        walletId: wallet.walletId,
        restoringStatus: StackRestoringStatus.restoring,
      );

      switch (wallet) {
        case EpiccashWallet():
          await wallet.init(isRestore: true);
          break;

        case MimblewimblecoinWallet():
          await wallet.init(isRestore: true);
          break;

        case CryptonoteWallet():
          await wallet.init(isRestore: true);
          await wallet.open();
          break;

        case XelisWallet():
          await wallet.init(isRestore: true);
          break;

        case ZcashWallet():
          await wallet.init(isRestore: true);
          break;

        default:
          await wallet.init();
      }

      if (wallet case ZcashWallet()) {
        final operation = ZcashRestoredWalletOperation.forWallet(
          wallet,
          isRescan: true,
        );
        SWB.registerZcashRestore(operation);
        final bool ready;
        try {
          ready = await operation.run(
            acquireParameters: (taskFactory) async {
              final task = taskFactory();
              var acceptingStates = true;
              void handleState(SaplingParameterState state) {
                if (!acceptingStates) return;
                final activity = zcashRestoreParameterActivity(state);
                uiState.updateActivity(
                  walletId: wallet.walletId,
                  label: activity.label,
                  progress: activity.progress,
                );
              }

              final subscription = task.states.listen(handleState);
              if (task case SaplingParameterTaskStateSnapshot(
                :final currentState?,
              )) {
                handleState(currentState);
              }
              try {
                await task.result;
                return true;
              } finally {
                acceptingStates = false;
                unawaited(subscription.cancel());
                uiState.clearActivity(walletId: wallet.walletId);
              }
            },
          );
        } finally {
          SWB.unregisterZcashRestore(operation);
        }
        if (!ready) {
          if (mounted) {
            uiState.update(
              walletId: wallet.walletId,
              restoringStatus: StackRestoringStatus.failed,
            );
          }
          return;
        }
      } else {
        await wallet.recover(isRescan: true);
      }

      final address = await wallet.getCurrentReceivingAddress();

      await wallet.exit();
      didExit = true;

      if (mounted) {
        uiState.update(
          walletId: wallet.walletId,
          restoringStatus: StackRestoringStatus.success,
          address: address?.value,
        );
      }
    } catch (e, s) {
      Logging.instance.e(
        "retry SWB single wallet tapped",
        error: e,
        stackTrace: s,
      );
      if (mounted) {
        uiState.update(
          walletId: wallet.walletId,
          restoringStatus: StackRestoringStatus.failed,
        );
      }
    } finally {
      uiState.clearActivity(walletId: wallet.walletId);
      if (!didExit) await wallet.exit();
    }
  }

  Widget _getIconForState(StackRestoringStatus state) {
    switch (state) {
      case StackRestoringStatus.waiting:
        return SvgPicture.asset(
          Assets.svg.loader,
          color: Theme.of(
            context,
          ).extension<StackColors>()!.buttonBackSecondary,
        );
      case StackRestoringStatus.restoring:
        return const LoadingIndicator();
      // return SvgPicture.asset(
      //   Assets.svg.loader,
      //   color: Theme.of(context).extension<StackColors>()!.accentColorGreen,
      // );
      case StackRestoringStatus.success:
        return SvgPicture.asset(
          Assets.svg.checkCircle,
          color: Theme.of(context).extension<StackColors>()!.accentColorGreen,
        );
      case StackRestoringStatus.failed:
        return SvgPicture.asset(
          Assets.svg.circleAlert,
          color: Theme.of(context).extension<StackColors>()!.textError,
        );
    }
  }

  @override
  void initState() {
    provider = widget.provider;
    super.initState();
  }

  @override
  Widget build(BuildContext context) {
    final coin = ref.watch(provider.select((value) => value.coin));
    final restoringStatus = ref.watch(
      provider.select((value) => value.restoringState),
    );
    final address = ref.watch(provider.select((value) => value.address));
    final activityLabel = ref.watch(
      provider.select((value) => value.activityLabel),
    );
    final activityProgress = ref.watch(
      provider.select((value) => value.activityProgress),
    );
    final Text? subTitle = restoringStatus == StackRestoringStatus.failed
        ? Text(
            "Unable to restore. Tap icon to retry.",
            style: STextStyles.errorSmall(context),
          )
        : activityLabel != null
        ? Text(
            activityProgress == null
                ? activityLabel
                : '$activityLabel '
                      '${(activityProgress * 100).clamp(0, 100).toStringAsFixed(0)}%',
            style: STextStyles.infoSmall(context),
          )
        : address != null
        ? Text(address, style: STextStyles.infoSmall(context))
        : null;
    return !Util.isDesktop
        ? RestoringItemCard(
            left: SizedBox(
              width: 32,
              height: 32,
              child: RoundedContainer(
                padding: const EdgeInsets.all(0),
                color: ref.watch(pCoinColor(coin)),
                child: Center(
                  child: SvgPicture.file(
                    File(ref.watch(coinIconProvider(coin))),
                    height: 20,
                    width: 20,
                  ),
                ),
              ),
            ),
            onRightTapped: restoringStatus == StackRestoringStatus.failed
                ? _retry
                : null,
            right: SizedBox(
              width: 20,
              height: 20,
              child: _getIconForState(
                ref.watch(provider.select((value) => value.restoringState)),
              ),
            ),
            title:
                "${ref.watch(provider.select((value) => value.walletName))} (${coin.ticker})",
            subTitle: subTitle,
            button: restoringStatus == StackRestoringStatus.failed
                ? Container(
                    height: 20,
                    decoration: BoxDecoration(
                      color: Theme.of(
                        context,
                      ).extension<StackColors>()!.buttonBackSecondary,
                      borderRadius: BorderRadius.circular(1000),
                    ),
                    child: RawMaterialButton(
                      materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                      splashColor: Theme.of(
                        context,
                      ).extension<StackColors>()!.highlight,
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(1000),
                      ),
                      onPressed: () async {
                        final mnemonic = ref.read(provider).mnemonic;

                        if (mnemonic != null) {
                          Navigator.of(context).push(
                            RouteGenerator.getRoute(
                              builder: (_) => RecoverPhraseView(
                                walletName: ref.read(provider).walletName,
                                mnemonic: mnemonic.split(" "),
                              ),
                            ),
                          );
                        }
                      },
                      child: Padding(
                        padding: const EdgeInsets.symmetric(horizontal: 8.0),
                        child: Text(
                          "Show recovery phrase",
                          style: STextStyles.infoSmall(context).copyWith(
                            color: Theme.of(
                              context,
                            ).extension<StackColors>()!.accentColorDark,
                          ),
                        ),
                      ),
                    ),
                  )
                : null,
          )
        : RoundedContainer(
            padding: const EdgeInsets.all(0),
            color: Theme.of(context).extension<StackColors>()!.popupBG,
            borderColor: Theme.of(context).extension<StackColors>()!.background,
            child: RestoringItemCard(
              left: SizedBox(
                width: 32,
                height: 32,
                child: RoundedContainer(
                  padding: const EdgeInsets.all(0),
                  color: ref.watch(pCoinColor(coin)),
                  child: Center(
                    child: SvgPicture.file(
                      File(ref.watch(coinIconProvider(coin))),
                      height: 20,
                      width: 20,
                    ),
                  ),
                ),
              ),
              onRightTapped: restoringStatus == StackRestoringStatus.failed
                  ? _retry
                  : null,
              right: SizedBox(
                width: 20,
                height: 20,
                child: _getIconForState(
                  ref.watch(provider.select((value) => value.restoringState)),
                ),
              ),
              title:
                  "${ref.watch(provider.select((value) => value.walletName))} (${coin.ticker})",
              subTitle: subTitle,
              button: restoringStatus == StackRestoringStatus.failed
                  ? Container(
                      height: 20,
                      decoration: BoxDecoration(
                        color: Theme.of(
                          context,
                        ).extension<StackColors>()!.buttonBackSecondary,
                        borderRadius: BorderRadius.circular(1000),
                      ),
                      child: RawMaterialButton(
                        materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
                        splashColor: Theme.of(
                          context,
                        ).extension<StackColors>()!.highlight,
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(1000),
                        ),
                        onPressed: () async {
                          final mnemonic = ref.read(provider).mnemonic;

                          if (mnemonic != null) {
                            Navigator.of(context).push(
                              RouteGenerator.getRoute(
                                builder: (_) => RecoverPhraseView(
                                  walletName: ref.read(provider).walletName,
                                  mnemonic: mnemonic.split(" "),
                                ),
                              ),
                            );
                          }
                        },
                        child: Padding(
                          padding: const EdgeInsets.symmetric(horizontal: 8.0),
                          child: Text(
                            "Show recovery phrase",
                            style: STextStyles.infoSmall(context).copyWith(
                              color: Theme.of(
                                context,
                              ).extension<StackColors>()!.accentColorDark,
                            ),
                          ),
                        ),
                      ),
                    )
                  : null,
            ),
          );
  }
}
